import pandas as pd
import numpy as np
from datetime import timedelta

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    target_snapshot = inputs["target_snapshot"].copy()
    cdc_events = inputs["cdc_events"].copy()
    watermark = inputs["watermark"].copy()

    # Extract high_ts from watermark (single row)
    high_ts = watermark["high_ts"].iloc[0]

    # Filter events with event_ts > high_ts
    new_events = cdc_events[cdc_events["event_ts"] > high_ts].copy()

    # If no new events, return current snapshot
    if len(new_events) == 0:
        return {"new_snapshot": target_snapshot[["user_id", "email", "status", "status_ts"]]}

    # Sort events by user_id, then event_ts, then event_seq for deterministic processing
    new_events = new_events.sort_values(by=["user_id", "event_ts", "event_seq"]).reset_index(drop=True)

    # Create a dictionary to track the latest state per user
    # Key: user_id, Value: {email, status, status_ts}
    user_state = {}

    # Initialize user_state from target_snapshot
    for _, row in target_snapshot.iterrows():
        user_id = row["user_id"]
        user_state[user_id] = {
            "email": row["email"],
            "status": row["status"],
            "status_ts": row["status_ts"]
        }

    # Process events sequentially per user
    for _, event in new_events.iterrows():
        user_id = event["user_id"]
        event_ts = event["event_ts"]
        op = event["op"]
        email = event["email"]

        # Get current state for this user (or initialize if new)
        if user_id not in user_state:
            user_state[user_id] = {
                "email": None,
                "status": None,
                "status_ts": None
            }

        current = user_state[user_id]

        if op == "U":
            # Update operation
            if current["status"] == "DELETED":
                # Check if update arrives strictly more than 7 days after deletion
                if current["status_ts"] is not None:
                    days_since_deletion = (event_ts - current["status_ts"]) / pd.Timedelta(days=1)
                    if days_since_deletion > 7:
                        # Resurrection allowed
                        user_state[user_id] = {
                            "email": email,
                            "status": "ACTIVE",
                            "status_ts": event_ts
                        }
                    # else: discard the update (deletion is sticky)
                else:
                    # Edge case: status is DELETED but status_ts is None (shouldn't happen)
                    user_state[user_id] = {
                        "email": email,
                        "status": "ACTIVE",
                        "status_ts": event_ts
                    }
            else:
                # Update on ACTIVE or new user
                user_state[user_id] = {
                    "email": email,
                    "status": "ACTIVE",
                    "status_ts": event_ts
                }
        elif op == "D":
            # Soft delete operation
            user_state[user_id] = {
                "email": email,
                "status": "DELETED",
                "status_ts": event_ts
            }

    # Build new_snapshot from user_state
    result_rows = []
    for user_id, state in sorted(user_state.items()):
        result_rows.append({
            "user_id": user_id,
            "email": state["email"],
            "status": state["status"],
            "status_ts": state["status_ts"]
        })

    new_snapshot = pd.DataFrame(result_rows)

    # Ensure correct dtypes
    if len(new_snapshot) > 0:
        new_snapshot["user_id"] = new_snapshot["user_id"].astype("int64")
        new_snapshot["email"] = new_snapshot["email"].astype("object")
        new_snapshot["status"] = new_snapshot["status"].astype("object")
        new_snapshot["status_ts"] = pd.to_datetime(new_snapshot["status_ts"], utc=False)
    else:
        new_snapshot = pd.DataFrame({
            "user_id": pd.Series([], dtype="int64"),
            "email": pd.Series([], dtype="object"),
            "status": pd.Series([], dtype="object"),
            "status_ts": pd.Series([], dtype="datetime64[us]")
        })

    return {"new_snapshot": new_snapshot}
